type User = { id: number; name: string };
function parseUser(value: unknown): User {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) throw new TypeError('Invalid user');
  if (!('id' in value) || typeof value.id !== 'number' || !Number.isSafeInteger(value.id) || value.id <= 0) throw new TypeError('Invalid id');
  if (!('name' in value) || typeof value.name !== 'string' || !value.name.trim()) throw new TypeError('Invalid name');
  return { id: value.id, name: value.name.trim() };
}
